def cards():return '<div class="expertise-grid">'+''.join(f'<a class="expertise-card" href="{u("services/"+s[0]+"/")}"><span class="card-index">{s[1]} <span>↗</span></span><h3>{s[2]}</h3><p>{s[4]}</p><span class="card-bottom">EXPLORE EXPERTISE</span></a>' for s in SERV)+'</div>'
