 labels=['A CLEARER<br><em>MESSAGE.</em>','THE GIFT.<br><em>THE OFFER.</em>','BETTER<br><em>CONNECTIONS.</em>','THE STORY<br><em>BEHIND IT.</em>','THE RIGHT<br><em>PARTNER.</em>','BEYOND<br><em>THE VIEWS.</em>']
