 return f'<form class="consultation-inquiry" data-kind="{kind}" data-email="{e(address)}"><label>Your name<input name="name" required autocomplete="name" maxlength="120"></label><label>Your email<input name="email" type="email" required autocomplete="email" maxlength="200"></label>{fields}<button class="solid" type="submit">Prepare inquiry email ↗</button><p class="fine">This opens a draft in your email app. Review it and press Send there. Nothing is submitted by this website. If your email app does not open, use the direct email link.</p><p class="inquiry-status" role="status"></p></form>'

