 for x in ART:page('blog/'+x['slug']+'/',x['title'],x['title'],f'<article class="article-page wrap"><nav class="breadcrumb" aria-label="Breadcrumb">{a("blog/","The Blog")} / {e(x["category"])}</nav><span class="eyebrow">{e(x["category"].upper())}</span><h1>{e(x["title"])}</h1><p class="byline">Zawatu Editorial · 2 November 2026 · Practical guide</p><div class="article-body">{x["body"]}</div><div class="article-end">{a("consultation/","Explore a consultation ↗","text-link")}<button class="share-link">Copy article link</button><span class="share-status" role="status"></span></div></article>','blog',x)
 page('partnerships/','Partnerships','Collaborate with Zawatu on media, campaigns and commercial opportunities.',hero('PARTNER WITH US','Different strengths.<br><em>A shared opportunity.</em>','We welcome relevant conversations with brands, sponsors, creators, media, suppliers and organisers, locally and internationally.')+'<section class="section wrap"><div class="three-grid"><article><h3>Brands & sponsors</h3><p>Support a defined series or campaign with clear placements, dates and reporting.</p></article><article><h3>Creators & media</h3><p>Bring a story, production skill or distribution opportunity. Rights and compensation are agreed in advance.</p></article><article><h3>Suppliers & venues</h3><p>Share your capabilities and delivery arrangements. An introduction is not an order.</p></article></div></section>'+cta())
 page('consulting/','Consulting','Choose business growth advice from Zawatu or technical consulting with Elvis Ndayishimiye.',hero('CONSULTING','A focused question.<br><em>A clearer next step.</em>','Choose the expertise that fits your challenge. Business growth and technical consulting have separate scopes and inquiry routes.')+f'<section class="section wrap"><div class="consulting-grid"><article class="consulting-offer"><span class="eyebrow">ZAWATU / BUSINESS GROWTH</span><h2>Turn an opportunity<br><em>into a plan.</em></h2><p>Marketing, visibility, sales and commercial partnerships. One focused challenge, practical next actions.</p><p class="consult-price">100,000 BIF <span>or US$35</span></p><p class="fine">45 minutes · Separate fixed prices · Google Meet</p>{a("consultation/","Explore business consultation ↗","solid")}</article><article class="consulting-offer"><span class="eyebrow">TECHNICAL CONSULTING / ELVIS NDAYISHIMIYE</span><h2>Think through<br><em>your system.</em></h2><p>Data systems, software architecture, data engineering and DevOps. Advice shaped around your context and delivery constraints.</p><p class="consult-price">Scoped to your needs</p><p class="fine">Advisory calls and assessments quoted separately</p>{a("consulting/technical/","Discuss a technical challenge ↗","outline-button")}</article></div></section>','consulting')
 request=consultation_form('business',S['email'])
